package practice;

import java.util.List;
import java.util.Map;
import java.util.concurrent.ForkJoinPool;
import java.util.stream.Collectors;

/**
 * Refreshes the catalogue's prices every night from the rate service. A lookup is a network call
 * that takes a few hundred milliseconds, so the refresh looks up many SKUs at once.
 */
public class PriceRefresh {

    /** The rate service: one blocking network call per SKU. */
    public interface RateService {
        long priceCents(String sku);
    }

    private final RateService rates;
    private final int workers;

    /**
     * @param rates   the rate service
     * @param workers how many threads the refresh may use for its lookups
     */
    public PriceRefresh(RateService rates, int workers) {
        this.rates = rates;
        this.workers = workers;
    }

    /** The current price of every SKU, by SKU. A failed lookup fails the whole refresh. */
    public Map<String, Long> refresh(List<String> skus) {
        ForkJoinPool pool = new ForkJoinPool(workers);
        try {
            return pool.submit(() -> lookUpAll(skus)).join();
        } finally {
            pool.shutdown();
        }
    }

    /** The price of every SKU, by SKU, looked up several at a time. */
    Map<String, Long> lookUpAll(List<String> skus) {
        return skus.parallelStream().collect(Collectors.toMap(sku -> sku, rates::priceCents));
    }
}

package practice;

import java.util.List;
import java.util.Set;
import java.util.TreeMap;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ForkJoinPool;
import java.util.concurrent.ForkJoinWorkerThread;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            Set<Thread> lookupThreads = ConcurrentHashMap.newKeySet();
            PriceRefresh refresh = new PriceRefresh(sku -> {
                lookupThreads.add(Thread.currentThread());
                return 450L + sku.length() * 100L;
            }, 4);
            var prices = refresh.refresh(List.of("BOWL-12", "SPOON-7", "FORK-5", "PLATE-330", "KNIFE-9"));
            System.out.println("prices: " + new TreeMap<>(prices));
            System.out.println("at most 4 lookup threads: " + (lookupThreads.size() <= 4));
            System.out.println("all on the refresh's own pool: " + lookupThreads.stream().allMatch(t ->
                    t instanceof ForkJoinWorkerThread w && w.getPool() != ForkJoinPool.commonPool()));
            System.out.println("empty list: " + refresh.refresh(List.of()));
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }
}

